    /// Регрессия на живой репорт пользователя: окклюдер, частично закрытый
    /// ДРУГИМ окном, стоящим выше него в z-order (`windows[0]` — самое
    /// верхнее, порядок кэша трекера), даёт вырезанный прямоугольник, а не
    /// исходный целиком — иначе стикер оставался спрятанным даже там, где
    /// окклюдер физически не виден. Allow-list с правилом `notepad.exe`:
    /// `notepad` — «разрешённое» окно (сверху, `is_occluder` false, само по
    /// себе рект в вывод не даёт), `chrome` не подходит под правило —
    /// окклюдер (сравнение с `allowlist_matches_by_short_process_name`/
    /// `allowlist_process_rule_no_exe_path_still_occludes` в occluders.rs).
    #[test]
    fn occluder_rects_for_subtracts_windows_above_in_z_order() {
        let on_top = window(
            Some("notepad.exe"),
            "поверх",
            "c",
            WindowRect {
                x: 0,
                y: 0,
                w: 50,
                h: 100,
            },
            false,
        );
        let occluder = window(
            Some("chrome.exe"),
            "t",
            "c",
            WindowRect {
                x: 0,
                y: 0,
                w: 100,
                h: 100,
            },
            false,
        );
        // z-order сверху вниз: `on_top` первым (топовое окно), `occluder` —
        // ниже (window_tracker.rs: «Кэш: Vec<WindowInfo> (порядок = z-order)»).
        let windows = vec![on_top, occluder];
        let rule = OverlapRule {
            process_name: Some("notepad.exe".to_string()),
            title_pattern: None,
        };
        let rects = occluder_rects_for(
            VisibilityMode::OverlapAllowlist,
            &[rule],
            // рабочий стол выбран — отдельного окклюдера нет
            true,
            false,
            &windows,
            &bounds(0, 0, 1920, 1080),
        );
        let total_area: i64 = rects.iter().map(|r| r.w as i64 * r.h as i64).sum();
        assert_eq!(
            total_area,
            100 * 100 - 50 * 100,
            "видимая площадь окклюдера — его rect минус то, что реально сверху"
        );
        for r in &rects {
            assert!(
                r.x >= 50,
                "куски не должны заходить в область on_top: {r:?}"
            );
        }
    }

    /// Окно, разрешённое allow-list'ом (само не окклюдер), но стоящее выше
    /// окклюдера в z-order и полностью его закрывающее, всё равно должно
    /// вычитать его площадь — маска реагирует на «что реально видно», а не
    /// только на другие окклюдеры (тот самый случай из репорта:
    /// переключились на постороннее/разрешённое окно — оно теперь сверху и
    /// закрывает исключённое окно, стикер обязан появиться под ним).
    #[test]
    fn occluder_rects_for_subtracts_non_matching_window_above_too() {
        let allowed_on_top = window(
            Some("notepad.exe"),
            "разрешённое",
            "c",
            WindowRect {
                x: 0,
                y: 0,
                w: 100,
                h: 100,
            },
            false,
        );
        let occluder = window(
            Some("chrome.exe"),
            "t",
            "c",
            WindowRect {
                x: 0,
                y: 0,
                w: 100,
                h: 100,
            },
            false,
        );
        let windows = vec![allowed_on_top, occluder];
        let rule = OverlapRule {
            process_name: Some("notepad.exe".to_string()),
            title_pattern: None,
        };
        let rects = occluder_rects_for(
            VisibilityMode::OverlapAllowlist,
            &[rule],
            // рабочий стол выбран — отдельного окклюдера нет
            true,
            false,
            &windows,
            &bounds(0, 0, 1920, 1080),
        );
        assert!(
            rects.is_empty(),
            "полностью закрытый сверху окклюдер не должен давать видимую площадь, а закрывающее окно само не окклюдер"
        );
    }

    #[test]
    fn window_exe_path_empty_pathbuf_is_none() {
        let w = window(None, "t", "c", WindowRect::default(), false);
        assert_eq!(window_exe_path(&w), None);
    }

    #[test]
    fn window_exe_path_nonempty_is_some() {
        let w = window(Some("chrome.exe"), "t", "c", WindowRect::default(), false);
        assert_eq!(window_exe_path(&w), Some("chrome.exe".to_string()));
    }

    #[test]
    fn window_rect_to_core_rejects_zero_or_negative_size() {
        assert_eq!(
            window_rect_to_core(&WindowRect {
                x: 0,
                y: 0,
                w: 0,
                h: 10
            }),
            None
        );
        assert_eq!(
            window_rect_to_core(&WindowRect {
                x: 0,
                y: 0,
                w: 10,
                h: -5
            }),
            None
        );
    }

    #[test]
    fn window_rect_to_core_converts_valid_rect() {
        assert_eq!(
            window_rect_to_core(&WindowRect {
                x: -10,
                y: 20,
                w: 100,
                h: 200
            }),
            Some(bounds(-10, 20, 100, 200))
        );
    }

    // --- M3: смена DPI (M3_PREP_NOTES.md §3.6) — синтетические переходы
    // 100/150/200%, без реального смешанного DPI-железа (см. докком
    // `dpi_change_scale_and_cursor`) ---

    #[test]
    fn dpi_change_scale_matches_standard_percents() {
        // 96/144/192 — стандартные Windows-точки 100/150/200% (dpi/96.0).
        assert_eq!(dpi_change_scale_and_cursor(1.0, 96, (0.0, 0.0)).0, 1.0);
        assert_eq!(dpi_change_scale_and_cursor(1.0, 144, (0.0, 0.0)).0, 1.5);
        assert_eq!(dpi_change_scale_and_cursor(1.0, 192, (0.0, 0.0)).0, 2.0);
    }

    /// Отношение `old_scale/new_scale` считается в f32 (см. докком
    /// `dpi_change_scale_and_cursor`) — для «некруглых» отношений вроде
    /// 1.0/1.5 это не бит-в-бит точное число, поэтому сравнение физической
    /// позиции ниже — с допуском, а не `assert_eq!` (стандартная практика
    /// для float-арифметики, не признак бага в самой функции).
    fn assert_close(a: f64, b: f64, msg: &str) {
        assert!((a - b).abs() < 1e-4, "{msg}: {a} vs {b}");
    }

    #[test]
    fn dpi_change_cursor_preserves_physical_position_100_to_150() {
        // 300 DIP при 100% = 300 физических px; при 150% та же физическая
        // точка — 200 DIP (300 / 1.5).
        let (scale, cursor) = dpi_change_scale_and_cursor(1.0, 144, (300.0, 150.0));
        assert_eq!(scale, 1.5);
        assert_close(cursor.0, 200.0, "x");
        assert_close(cursor.1, 100.0, "y");
    }

    #[test]
    fn dpi_change_cursor_preserves_physical_position_150_to_200() {
        // 150 DIP при 150% = 225 физических px; при 200% та же точка —
        // 112.5 DIP (225 / 2.0).
        let (scale, cursor) = dpi_change_scale_and_cursor(1.5, 192, (150.0, 300.0));
        assert_eq!(scale, 2.0);
        assert_close(cursor.0, 112.5, "x");
        assert_close(cursor.1, 225.0, "y");
    }

    #[test]
    fn dpi_change_cursor_preserves_physical_position_200_to_100() {
        // Обратный переход (монитор передвинули со 200% экрана на 100%) —
        // та же инвариантная физическая точка, ratio > 1 на этот раз.
        let (scale, cursor) = dpi_change_scale_and_cursor(2.0, 96, (100.0, 50.0));
        assert_eq!(scale, 1.0);
        assert_close(cursor.0, 200.0, "x");
        assert_close(cursor.1, 100.0, "y");
    }

    #[test]
    fn dpi_change_same_dpi_is_a_no_op_for_cursor() {
        // Дубль WM_DISPLAYCHANGE/WM_DPICHANGED на тот же DPI (случается —
        // M3_HOTPLUG_DESIGN.md §2 про идемпотентность дублей) не должен
        // сдвигать курсор ни на суб-пиксель.
        let (scale, cursor) = dpi_change_scale_and_cursor(1.5, 144, (77.0, 33.0));
        assert_eq!(scale, 1.5);
        assert_close(cursor.0, 77.0, "x");
        assert_close(cursor.1, 33.0, "y");
    }

    #[test]
    fn dpi_change_chain_100_150_200_preserves_original_physical_position() {
        // «Смешанный DPI» сквозь три перехода подряд (100% → 150% → 200%,
        // как если бы окно переезжало по мониторам с разным DPI, или один
        // монитор трижды сменил настройку) — физическая (px) позиция курсора
        // должна остаться неизменной на каждом шаге, а не только на первом.
        let start_dip = (960.0, 540.0);
        let physical = start_dip.0 * 1.0;

        let (scale_150, cursor_150) = dpi_change_scale_and_cursor(1.0, 144, start_dip);
        assert_close(
            cursor_150.0 * scale_150 as f64,
            physical,
            "физика после 150%",
        );

        let (scale_200, cursor_200) = dpi_change_scale_and_cursor(scale_150, 192, cursor_150);
        assert_close(
            cursor_200.0 * scale_200 as f64,
            physical,
            "физика после 200%",
        );

        let (scale_100, cursor_100) = dpi_change_scale_and_cursor(scale_200, 96, cursor_200);
        assert_eq!(scale_100, 1.0);
        // Полный круг 100→150→200→100 возвращает исходную DIP-позицию.
        assert_close(cursor_100.0, start_dip.0, "x после полного круга");
        assert_close(cursor_100.1, start_dip.1, "y после полного круга");
    }

    // --- Полоса перемотки видео (запрос пользователя 2026-08-22) ---

    /// Видео-стикер `w`×`h` с центром в `(cx, cy)` на мониторе `monitor`.
    fn video_sticker(monitor: &str, cx: f64, cy: f64, w: f64, h: f64) -> Sticker {
        Sticker {
            id: Uuid::new_v4(),
            source: StickerSource::File {
                path: PathBuf::from(r"C:\video.mp4"),
                media_type: MediaType::Video,
            },
            placement: Placement {
                monitor_id: monitor_id(monitor),
                cx,
                cy,
                w,
                h,
            },
            ..Default::default()
        }
    }

    // --- Попадание в живой кусок окна (2026-09-11) ---

    fn crop_sticker(cx: f64, cy: f64, w: f64, h: f64, minimized: bool) -> Sticker {
        let mut s = Sticker::new_window_crop(
            rst_core::model::CropWindowKey {
                exe_path: std::path::PathBuf::from(r"C:\app\app.exe"),
                title: "Окно".to_string(),
                class: "Cls".to_string(),
            },
            rst_core::model::CropRect::default(),
            monitor_id("main"),
            cx,
            cy,
            w,
            h,
        );
        if let StickerSource::WindowCrop { minimized: m, .. } = &mut s.source {
            *m = minimized;
        }
        s
    }

    fn cfg_with(stickers: Vec<Sticker>) -> Config {
        Config {
            stickers,
            ..Config::default()
        }
    }

    #[test]
    fn window_crop_at_finds_the_crop_under_the_cursor() {
        let cfg = cfg_with(vec![crop_sticker(500.0, 400.0, 200.0, 100.0, false)]);
        let mon = one_monitor();
        let hit = window_crop_at(&cfg, &mon, 500, 400).expect("центр куска");
        assert_eq!(hit.sticker, cfg.stickers[0].id);
        assert_eq!(hit.monitor, monitor_id("main"));
        assert!(
            window_crop_at(&cfg, &mon, 500, 200).is_none(),
            "выше куска попадания быть не должно"
        );
    }

    #[test]
    fn window_crop_at_takes_the_topmost_when_they_overlap() {
        // Порядок слоёв — это порядок списка, как и везде в проекте:
        // последний нарисован поверх, значит он и ловит курсор.
        let lower = crop_sticker(500.0, 400.0, 200.0, 100.0, false);
        let upper = crop_sticker(500.0, 400.0, 200.0, 100.0, false);
        let upper_id = upper.id;
        let cfg = cfg_with(vec![lower, upper]);
        let hit = window_crop_at(&cfg, &one_monitor(), 500, 400).expect("попадание");
        assert_eq!(hit.sticker, upper_id, "ловит верхний, а не первый в списке");
    }

    #[test]
    fn window_crop_at_ignores_ordinary_stickers() {
        // Обвязка окна — только у кусков. Обычная картинка под курсором не
        // должна снимать кликопрозрачность: это перехватило бы чужие клики
        // на ровном месте.
        let mut plain = crop_sticker(500.0, 400.0, 200.0, 100.0, false);
        plain.source = StickerSource::File {
            path: std::path::PathBuf::from("a.png"),
            media_type: MediaType::Image,
        };
        let cfg = cfg_with(vec![plain]);
        assert!(window_crop_at(&cfg, &one_monitor(), 500, 400).is_none());
    }

    #[test]
    fn window_crop_at_ignores_hidden_crop() {
        let mut s = crop_sticker(500.0, 400.0, 200.0, 100.0, false);
        s.visible = false;
        let cfg = cfg_with(vec![s]);
        assert!(
            window_crop_at(&cfg, &one_monitor(), 500, 400).is_none(),
            "скрытый кусок курсор не ловит — его на экране нет"
        );
    }

    #[test]
    fn minimized_crop_is_caught_by_its_icon_not_by_its_old_place() {
        // Свёрнутый кусок ловится по иконке у края экрана. Считать попадание
        // по месту, где он был, — значит сделать иконку ненажимаемой, а
        // пустоту под ней нажимаемой.
        let cfg = cfg_with(vec![crop_sticker(500.0, 400.0, 200.0, 100.0, true)]);
        let mon = one_monitor();
        assert!(
            window_crop_at(&cfg, &mon, 500, 400).is_none(),
            "на старом месте свёрнутого куска ловить нечего"
        );
        let piece = hittest::aabb(&cfg.stickers[0].placement, 0.0);
        let icon = window_crop_chrome::collapsed_icon_rect(
            piece,
            DipRect::new(0.0, 0.0, 1920.0, 1080.0),
            &[],
        )
        .expect("место под иконку");
        let hit = window_crop_at(
            &cfg,
            &mon,
            (icon.x + icon.w / 2.0) as i32,
            (icon.y + icon.h / 2.0) as i32,
        );
        assert_eq!(
            hit.map(|h| h.sticker),
            Some(cfg.stickers[0].id),
            "по иконке свёрнутый кусок обязан ловиться"
        );
    }

    #[test]
    fn crop_bar_above_the_piece_is_part_of_it() {
        // Полоса лежит поверх верхней кромки, но у куска на самом верху
        // экрана прижимается к границе монитора и может выйти за тело.
        // Кнопки в такой полосе обязаны оставаться нажимаемыми.
        let cfg = cfg_with(vec![crop_sticker(500.0, 60.0, 200.0, 100.0, false)]);
        let piece = hittest::aabb(&cfg.stickers[0].placement, 0.0);
        let layout = window_crop_chrome::chrome_layout(piece, 0.0, 1080.0);
        let hit = window_crop_at(
            &cfg,
            &one_monitor(),
            (layout.close.x + layout.close.w / 2.0) as i32,
            (layout.close.y + layout.close.h / 2.0) as i32,
        );
        assert!(hit.is_some(), "точка на кнопке закрытия принадлежит куску");
    }

    #[test]
    fn a_hairline_crop_still_gets_a_window_wide_enough_for_its_buttons() {
        // Кусок шириной в несколько точек — обычная промашка рукой при
        // протяжке. Окно такого размера не смогло бы показать три кнопки
        // полосы: при ширине меньше четырёх точек кнопке достаётся ноль
        // пикселей, полоса целиком становится ручкой, и кусок нельзя ни
        // закрыть, ни свернуть, ни закрепить (ревью P5, 2026-09-13).
        let cfg = cfg_with(vec![crop_sticker(500.0, 400.0, 2.0, 3.0, false)]);
        let bounds =
            crop_window_bounds(&cfg.stickers[0], &one_monitor()).expect("монитор стикера есть");
        assert!(
            bounds.w >= MIN_CROP_SIDE_DIP && bounds.h >= MIN_CROP_SIDE_DIP,
            "окно куска не уже минимума: {}×{}",
            bounds.w,
            bounds.h
        );
        // Та же арифметика, что у полосы: кнопке обязана достаться ширина.
        assert!(bounds.w / 4 > 0, "в полосе такой ширины кнопки существуют");
    }

    #[test]
    fn a_crop_bigger_than_the_minimum_keeps_its_own_size() {
        // Зажим не должен трогать нормальный кусок: иначе он тихо менял бы
        // размер окна за спиной пользователя.
        let cfg = cfg_with(vec![crop_sticker(500.0, 400.0, 200.0, 100.0, false)]);
        let bounds =
            crop_window_bounds(&cfg.stickers[0], &one_monitor()).expect("монитор стикера есть");
        assert_eq!((bounds.w, bounds.h), (200, 100));
    }

    #[test]
    fn window_crop_at_returns_none_outside_any_monitor() {
        let cfg = cfg_with(vec![crop_sticker(500.0, 400.0, 200.0, 100.0, false)]);
        assert!(
            window_crop_at(&cfg, &one_monitor(), -5000, -5000).is_none(),
            "точка вне мониторов не даёт ни куска, ни паники"
        );
    }

    #[test]
    fn window_crop_at_uses_rotated_bounds() {
        // Повёрнутый кусок занимает БОЛЬШЕ места по осям, чем его
        // собственные ширина и высота. Считать попадание по неповёрнутой
        // рамке значило бы терять клики по его углам.
        let mut s = crop_sticker(500.0, 400.0, 200.0, 40.0, false);
        s.transform.rotation = std::f64::consts::FRAC_PI_2;
        let cfg = cfg_with(vec![s]);
        let hit = window_crop_at(&cfg, &one_monitor(), 500, 480);
        assert!(
            hit.is_some(),
            "после поворота на 90° кусок вытянулся по вертикали и точка внутри него"
        );
    }

    fn one_monitor() -> HashMap<MonitorId, MonitorBounds> {
        HashMap::from([(
            monitor_id("main"),
            MonitorBounds {
                id: monitor_id("main"),
                bounds_px: bounds(0, 0, 1920, 1080),
                scale: 1.0,
            },
        )])
    }

    /// Медиа-клавиши НЕ зависят от настройки полосы перемотки.
    ///
    /// Ровно тот баг, который поймал пользователь 2026-09-01: у его
    /// видео-стикера `show_timeline: false` (замер `config.json`), и
    /// PgUp/PgDn не работали вовсе — хотя к полосе перемотки громкость
    /// отношения не имеет. Полоса при тех же данных цели не даёт, и это
    /// правильно: настройка про неё и есть.
    #[test]
    fn media_keys_ignore_the_timeline_setting() {
        let mut cfg = Config::default();
        let mut sticker = video_sticker("main", 500.0, 500.0, 400.0, 300.0);
        sticker.playback.show_timeline = false;
        let id = sticker.id;
        cfg.stickers.push(sticker);
        let mut edit = mask_gate_edit_state();
        // Вне режима редактирования: цель берётся по курсору.
        edit.active = false;
        let cursor = Some((500, 500));

        assert_eq!(
            media_keys_target(&edit, &cfg, &one_monitor(), cursor).map(|(id, _)| id),
            Some(id),
            "громкость обязана работать при выключенной полосе"
        );
        assert_eq!(
            video_timeline_target(&edit, &cfg, &|_| true, &one_monitor(), cursor),
            None,
            "полоса при выключенной настройке не показывается — это её право"
        );
    }

    /// В режиме редактирования цель медиа-клавиш — ВЫДЕЛЕННЫЙ стикер, а не
    /// тот, что под курсором: тянуться мышью к стикеру, чтобы убавить ему
    /// звук, там незачем.
    #[test]
    fn media_keys_follow_selection_in_edit_mode() {
        let mut cfg = Config::default();
        let sticker = video_sticker("main", 500.0, 500.0, 400.0, 300.0);
        let id = sticker.id;
        cfg.stickers.push(sticker);
        let mut edit = mask_gate_edit_state();
        edit.active = true;
        edit.selection.select(id);

        // Курсор в другом углу экрана — цель всё равно выделенный стикер.
        assert_eq!(
            media_keys_target(&edit, &cfg, &one_monitor(), Some((10, 10))).map(|(id, _)| id),
            Some(id)
        );
    }

    /// Скрытый стикер целью не становится: его нет на экране, наводиться
    /// не на что, а звук у него и так приглушён настройкой
    /// `mute_invisible_stickers`.
    #[test]
    fn media_keys_skip_a_hidden_sticker() {
        let mut cfg = Config::default();
        let mut sticker = video_sticker("main", 500.0, 500.0, 400.0, 300.0);
        sticker.visible = false;
        cfg.stickers.push(sticker);
        let mut edit = mask_gate_edit_state();
        edit.active = false;
        assert_eq!(
            media_keys_target(&edit, &cfg, &one_monitor(), Some((500, 500))),
            None
        );
    }

    /// Не-видео под курсором клавиши не забирает: пробел и PgUp/PgDn
    /// перехватываются у всей системы, и держать их ради картинки нельзя.
    #[test]
    fn media_keys_ignore_a_picture() {
        let mut cfg = Config::default();
        cfg.stickers.push(zone_test_sticker(0.0));
        let mut edit = mask_gate_edit_state();
        edit.active = false;
        assert_eq!(
            media_keys_target(&edit, &cfg, &one_monitor(), Some((200, 200))),
            None
        );
    }

    /// В режиме редактирования полоса принадлежит выделенному видео —
    /// независимо от того, где курсор: там она часть редактирования.
    #[test]
    fn timeline_target_in_edit_mode_follows_selection() {
        let mut cfg = Config::default();
        let sticker = video_sticker("main", 500.0, 500.0, 400.0, 300.0);
        let id = sticker.id;
        cfg.stickers.push(sticker);
        let mut edit = mask_gate_edit_state();
        edit.selection.select(id);

        let target = video_timeline_target(&edit, &cfg, &|_| true, &one_monitor(), None);
        assert_eq!(
            target.map(|(id, _, hover)| (id, hover)),
            Some((id, false)),
            "выделенное видео получает полосу, режим — не hover"
        );
    }

    /// Пока длительность неизвестна, перематывать нечего — полосы нет.
    #[test]
    fn timeline_target_needs_known_duration() {
        let mut cfg = Config::default();
        let sticker = video_sticker("main", 500.0, 500.0, 400.0, 300.0);
        let id = sticker.id;
        cfg.stickers.push(sticker);
        let mut edit = mask_gate_edit_state();
        edit.selection.select(id);

        assert!(video_timeline_target(&edit, &cfg, &|_| false, &one_monitor(), None).is_none());
    }

    /// Мульти-выделение: «перемотать их все» — бессмысленная операция.
    #[test]
    fn timeline_target_absent_for_multiselection() {
        let mut cfg = Config::default();
        let a = video_sticker("main", 300.0, 300.0, 200.0, 200.0);
        let b = video_sticker("main", 800.0, 300.0, 200.0, 200.0);
        let (ida, idb) = (a.id, b.id);
        cfg.stickers.push(a);
        cfg.stickers.push(b);
        let mut edit = mask_gate_edit_state();
        edit.selection.select(ida);
        edit.selection.select(idb);

        assert!(video_timeline_target(&edit, &cfg, &|_| true, &one_monitor(), None).is_none());
    }

    /// Вне режима редактирования полоса появляется только у видео с
    /// включённой настройкой и только под курсором.
    #[test]
    fn timeline_target_outside_edit_mode_needs_setting_and_hover() {
        let mut cfg = Config::default();
        let mut sticker = video_sticker("main", 500.0, 500.0, 400.0, 300.0);
        let id = sticker.id;
        sticker.playback.show_timeline = false;
        cfg.stickers.push(sticker);
        let mut edit = mask_gate_edit_state();
        edit.active = false;
        let mon = one_monitor();

        // Настройка выключена — полосы нет даже под курсором.
        assert!(
            video_timeline_target(&edit, &cfg, &|_| true, &mon, Some((500, 500))).is_none(),
            "без настройки полоса вне режима редактирования не показывается"
        );

        cfg.stickers[0].playback.show_timeline = true;
        assert_eq!(
            video_timeline_target(&edit, &cfg, &|_| true, &mon, Some((500, 500)))
                .map(|(id, _, hover)| (id, hover)),
            Some((id, true)),
            "курсор на стикере — полоса всплывает"
        );
        assert!(
            video_timeline_target(&edit, &cfg, &|_| true, &mon, Some((50, 50))).is_none(),
            "курсор мимо стикера — полосы нет"
        );
        assert!(
            video_timeline_target(&edit, &cfg, &|_| true, &mon, None).is_none(),
            "позиция курсора неизвестна — полосы нет"
        );
    }

    /// Стикеры перекрываются — полоса у верхнего: именно его человек видит
    /// под курсором.
    #[test]
    fn timeline_target_picks_topmost_under_cursor() {
        let mut cfg = Config::default();
        let mut low = video_sticker("main", 500.0, 500.0, 400.0, 300.0);
        low.order = 1;
        low.playback.show_timeline = true;
        let mut high = video_sticker("main", 500.0, 500.0, 400.0, 300.0);
        high.order = 5;
        high.playback.show_timeline = true;
        let top = high.id;
        cfg.stickers.push(low);
        cfg.stickers.push(high);
        let mut edit = mask_gate_edit_state();
        edit.active = false;

        assert_eq!(
            video_timeline_target(&edit, &cfg, &|_| true, &one_monitor(), Some((500, 500)))
                .map(|(id, _, _)| id),
            Some(top)
        );
    }

    /// Скрытый стикер (кнопка «глаз») полосу не получает: перематывать то,
    /// чего не видно, некуда.
    #[test]
    fn timeline_target_skips_hidden_sticker() {
        let mut cfg = Config::default();
        let mut sticker = video_sticker("main", 500.0, 500.0, 400.0, 300.0);
        sticker.playback.show_timeline = true;
        sticker.visible = false;
        cfg.stickers.push(sticker);
        let mut edit = mask_gate_edit_state();
        edit.active = false;

        assert!(
            video_timeline_target(&edit, &cfg, &|_| true, &one_monitor(), Some((500, 500)))
                .is_none()
        );
    }

    /// Курсор на втором мониторе переводится в его собственные DIP —
    /// с учётом и смещения, и масштаба.
    #[test]
    fn monitor_dip_at_maps_secondary_monitor_with_scale() {
        let mut mon = one_monitor();
        mon.insert(
            monitor_id("second"),
            MonitorBounds {
                id: monitor_id("second"),
                bounds_px: bounds(1920, 0, 2560, 1440),
                scale: 2.0,
            },
        );
        let (id, dip) = monitor_dip_at(1920 + 400, 200, &mon).expect("точка на втором мониторе");
        assert_eq!(*id, monitor_id("second"));
        assert_eq!(dip, (200.0, 100.0), "физические пиксели делятся на масштаб");

        assert!(
            monitor_dip_at(-5, 0, &mon).is_none(),
            "точка вне всех мониторов"
        );
    }

    // --- Геометрия закреплённых окон (SPEC.md «Закрепление окна»):
    // физический rect окна <-> DIP-`Placement`, для хит-теста/ручек ресайза
    // и обратно для `WindowPins::move_resize`.

    fn monitor_bounds_at(x: i32, y: i32, w: u32, h: u32, scale: f64) -> MonitorBounds {
        MonitorBounds {
            id: MonitorId("test-monitor".to_string()),
            bounds_px: bounds(x, y, w, h),
            scale,
        }
    }

    #[test]
    fn window_rect_to_placement_scale_one_no_origin() {
        let mon = monitor_bounds_at(0, 0, 1920, 1080, 1.0);
        let p = window_rect_to_placement(
            &WindowRect {
                x: 100,
                y: 50,
                w: 400,
                h: 300,
            },
            MonitorId("m".to_string()),
            &mon,
        );
        assert_eq!(p.cx, 300.0, "cx = x + w/2");
        assert_eq!(p.cy, 200.0, "cy = y + h/2");
        assert_eq!(p.w, 400.0);
        assert_eq!(p.h, 300.0);
        assert_eq!(p.monitor_id, MonitorId("m".to_string()));
    }

    #[test]
    fn window_rect_to_placement_subtracts_monitor_origin() {
        // Второй монитор правее основного: начало (1920, 0) в физике.
        let mon = monitor_bounds_at(1920, 0, 1920, 1080, 1.0);
        let p = window_rect_to_placement(
            &WindowRect {
                x: 1920 + 100,
                y: 50,
                w: 200,
                h: 100,
            },
            MonitorId("m".to_string()),
            &mon,
        );
        // Локальные DIP-координаты монитора — без сдвига на его начало.
        assert_eq!(p.cx, 100.0 + 100.0);
        assert_eq!(p.cy, 100.0);
    }

    #[test]
    fn window_rect_to_placement_divides_by_scale() {
        // 200% DPI: физические пиксели вдвое больше DIP.
        let mon = monitor_bounds_at(0, 0, 3840, 2160, 2.0);
        let p = window_rect_to_placement(
            &WindowRect {
                x: 200,
                y: 100,
                w: 800,
                h: 400,
            },
            MonitorId("m".to_string()),
            &mon,
        );
        assert_eq!(p.w, 400.0, "физические 800 / scale 2.0 = 400 DIP");
        assert_eq!(p.h, 200.0);
        assert_eq!(p.cx, 100.0 + 200.0);
        assert_eq!(p.cy, 50.0 + 100.0);
    }

    #[test]
    fn placement_to_physical_rect_is_inverse_of_window_rect_to_placement() {
        for (mon, rect) in [
            (
                monitor_bounds_at(0, 0, 1920, 1080, 1.0),
                WindowRect {
                    x: 100,
                    y: 50,
                    w: 400,
                    h: 300,
                },
            ),
            (
                monitor_bounds_at(1920, 0, 1920, 1080, 1.0),
                WindowRect {
                    x: 2020,
                    y: 50,
                    w: 200,
                    h: 100,
                },
            ),
            (
                monitor_bounds_at(0, 0, 3840, 2160, 2.0),
                WindowRect {
                    x: 201,
                    y: 101,
                    w: 801,
                    h: 401,
                },
            ),
        ] {
            let placement = window_rect_to_placement(&rect, MonitorId("m".to_string()), &mon);
            let (x, y, w, h) = placement_to_physical_rect(&placement, &mon);
            // Округление до целого физического px — допустимая погрешность
            // 1 px в любую сторону (та же точность, что у координат мыши).
            assert!((x - rect.x).abs() <= 1, "{rect:?}: x {x} vs {}", rect.x);
            assert!((y - rect.y).abs() <= 1, "{rect:?}: y {y} vs {}", rect.y);
            assert!((w - rect.w).abs() <= 1, "{rect:?}: w {w} vs {}", rect.w);
            assert!((h - rect.h).abs() <= 1, "{rect:?}: h {h} vs {}", rect.h);
        }
    }

    // --- M4: отсечение полностью перекрытых стикеров ---

    #[test]
    fn rect_contains_fully_inside() {
        assert!(rect_contains(
            &bounds(0, 0, 200, 200),
            &bounds(50, 50, 50, 50)
        ));
    }

    #[test]
    fn rect_contains_exact_match_is_contained() {
        assert!(rect_contains(
            &bounds(0, 0, 100, 100),
            &bounds(0, 0, 100, 100)
        ));
    }

    #[test]
    fn rect_contains_partial_overlap_is_not_contained() {
        assert!(!rect_contains(
            &bounds(0, 0, 100, 100),
            &bounds(50, 50, 100, 100)
        ));
    }

    #[test]
    fn rect_contains_disjoint_is_not_contained() {
        assert!(!rect_contains(
            &bounds(0, 0, 100, 100),
            &bounds(200, 200, 50, 50)
        ));
    }

    #[test]
    fn sticker_fully_covered_true_when_aabb_inside_one_occluder() {
        let placement = Placement {
            monitor_id: monitor_id("M1"),
            cx: 100.0,
            cy: 100.0,
            w: 40.0,
            h: 40.0,
        };
        // AABB без поворота (физические px при scale=1.0): (80,80,40,40).
        let occluder = bounds(0, 0, 500, 500);
        assert!(sticker_fully_covered(&placement, 0.0, 1.0, &[occluder]));
    }

    #[test]
    fn sticker_fully_covered_false_when_only_partially_covered() {
        let placement = Placement {
            monitor_id: monitor_id("M1"),
            cx: 100.0,
            cy: 100.0,
            w: 40.0,
            h: 40.0,
        };
        // Оклюдер накрывает только левую половину AABB (80,80,40,40).
        let occluder = bounds(0, 0, 100, 500);
        assert!(!sticker_fully_covered(&placement, 0.0, 1.0, &[occluder]));
    }

    #[test]
    fn sticker_fully_covered_false_when_covered_only_by_union_of_two() {
        // Консервативная проверка: покрытие ДВУМЯ прямоугольниками вместе не
        // считается — ни один из них по отдельности не содержит AABB целиком.
        let placement = Placement {
            monitor_id: monitor_id("M1"),
            cx: 100.0,
            cy: 100.0,
            w: 40.0,
            h: 40.0,
        };
        let left_half = bounds(0, 0, 100, 500);
        let right_half = bounds(100, 0, 100, 500);
        assert!(!sticker_fully_covered(
            &placement,
            0.0,
            1.0,
            &[left_half, right_half]
        ));
    }

    #[test]
    fn sticker_fully_covered_scales_aabb_by_monitor_scale() {
        let placement = Placement {
            monitor_id: monitor_id("M1"),
            cx: 100.0,
            cy: 100.0,
            w: 40.0,
            h: 40.0,
        };
        // При scale=2.0 AABB в физических px — (160,160,80,80); прямоугольник,
        // достаточный только для scale=1.0, больше не накрывает его целиком.
        let occluder_for_scale_1 = bounds(0, 0, 200, 200);
        assert!(!sticker_fully_covered(
            &placement,
            0.0,
            2.0,
            &[occluder_for_scale_1]
        ));
        let occluder_for_scale_2 = bounds(0, 0, 500, 500);
        assert!(sticker_fully_covered(
            &placement,
            0.0,
            2.0,
            &[occluder_for_scale_2]
        ));
    }

    #[test]
    fn sticker_fully_covered_false_for_sticker_tucked_in_rounded_corner() {
        // Найдено независимым ревью (2026-08-04): маска реально скруглена
        // (mainMaskPS, радиус MASK_CORNER_RADIUS_PX) — стикер, чей AABB
        // целиком внутри ПОЛНОГО прямоугольника-окклюдера, но лежит в зоне
        // угловой дуги, реально остаётся хоть немного видимым под маской.
        // AABB (2,2,8,8) — целиком в (0,0,200,200), но целиком и в зоне
        // дуги верхнего левого угла (уменьшенный на 8px прямоугольник
        // начинается только с (8,8)).
        let placement = Placement {
            monitor_id: monitor_id("M1"),
            cx: 6.0,
            cy: 6.0,
            w: 8.0,
            h: 8.0,
        };
        let occluder = bounds(0, 0, 200, 200);
        assert!(!sticker_fully_covered(&placement, 0.0, 1.0, &[occluder]));
    }

